INSERT INTO songs (song_number, title, category, songbook, song_text, tune, words, music, notes, lang, count, created_at) VALUES (3303, ' Мене Ти кличеш над водою', 0, 4, 'Куплет 1\n Мене Ти кличеш над водою\nДе не встоїть моя нога\nТебе в пригодах відшукаю\nОсяє віра океан\n\nПриспів\nТвоє ім''я прикличу я\nСховаю очі в небесах, душа моя\nСпочине у Твоїх руках\nТи мій Господь Твоїм є я\n\nКуплет 2\nВ глибинах вод перебуває\nТвоя безмежна благодать\nДе страх і темрява стискають\nТвоя рука покаже шлях\n\nПриспів\nТвоє ім''я прикличу я\nСховаю очі в небесах, душа моя\nСпочине у Твоїх руках\nТи мій Господь Твоїм є я\n\nКуплет 3\nДух, веди мене невпинно за Собою\nЩоб ходив я над водою куди б Ти не покликав\nПроведи мене в глибинах неосяжних\nЩоб міцніла віра завжди у Твоїх очах, Спаситель', '', '', '', '', 'ua', 1, NULL),
(3304, 'Немає, як Господь, святого', 0, 4, 'Куплет 1\nНемає, як Господь, святого,\nНема бо іншого, крім Нього,\nНемає скелі, як наш Бог,\nБо Він один, Він сильний Бог\n\nПриспів\nТи піднімаєш слабих,\nТи даєш нам сили.\nПідтримуєш Ти вірних,\nДаєш престоли слави\n\nКуплет 2\nЯ серцем своїм лину\nДо Тебе, сильний Царю,\nБо в Тобі знайду спокій,\nПідтримку для життя\n\nКуплет 3\nНе можу я без Тебе\nПрожити ні хвилини.\nТворець землі, Цар неба,\nОсяй моє життя', '', '', '', '', 'ua', 2, NULL),
(3305, 'Я хочу исполнить волю Твою', 0, 4, 'Куплет 1\nЯ хочу исполнить волю Твою\nПрошу, окропи меня Своей кровью\nЯ хочу увидеть славу Твою\nНаполни меня Своей любовью\n\nПриспів\nЯ без Тебя не знаю пути\nКуда мне идти и как мне жить\nПрошу, научи меня любить\nКак любишь Ты\n\nКуплет 2\nОчисти меня кровью Своей\nНе дай мне сойти с Твоих путей\nОчисти нас, очисти нас', '', '', '', '', 'ua', 2, NULL),
(3306, 'Благословить тебе й тримає', 0, 4, 'Куплет 1\nБлагословить тебе й тримає\nСвоїм світлом засяє на дорогу твою\nМилістю все нехай покриє\nДасть мир тобі\n\nКуплет 2\nАмінь! \nАмінь!\n\nКуплет 3\nЙого милість нехай буде\nЗ покоління в покоління\nНа сім''ї твоїй і дітях\nЙ їхніх дітях їхніх дітях\n\nКуплет 4\nХай Присутність Його буде \nВсе навколо наповняти \nБог попереду за Тебе \nВін з тобою Він з тобою\n\nКуплет 5\nКожен ранок кожен вечір\nКоли Йдеш Ти і приходиш\nКоли плачеш і радієш\nВін з тобою Він з тобою\n\nКуплет 6\nВін з тобою Він з тобою\nВін з тобою Він з тобою\nВін з тобою Він з тобою', '', '', '', '', 'ua', 7, NULL),
(3308, 'Кожен спрагнений', 0, 4, 'Куплет 1\nКожен спрагнений, іди та пий\nІз джерела води життя.\nХто любить Сина, хто вірить в Сина -\nТвоє життя цілком обновить Він.\n\nПриспів\nАлілуя, Тобі хвала!\nАлілуя, Тобі хвала!\nАлілуя, Тобі хвала!\nАлілуя, Тобі, Ісус, хвала!\n\nКуплет 2\nЯкщо ти знеміг, нема сил іти -\nВін поміч дасть на шляху земнім;\nТягарі знімає, сили відновляє,\nЗ усіх нещасть Він визволить тебе!\n\nКуплет 3\nТи проси вогню - і Він дасть тобі.\nСтанеш радісним і вперед підеш.\nЛиш Йому довірся, на Христа надійся.\nТвоє життя цілком обновить Він!', '', '', '', '', 'ua', 3, NULL),
(3309, 'Господь - Моя Скеля, Твердиня Моя', 0, 4, 'Куплет 1\nГосподь - Моя Скеля, Твердиня Моя,\nІ Він є Мій Спаситель.\nМій Бог-Моя Скеля, сховаюсь в Ній я,\nВін щит Мій, душі Відкупитель.\n\nКуплет  Пред Приспів\nЯ кличу: Преславний Господь!\nІ Він визволить від ворогів.\nВ тісноті я покличу Його,\nЩоб з Небес Він мені відповів.\n\nКуплет Приспів\nВін почує мій голос із Храму Свого,\nБо підношу молитви мої до Лиця Його.\nВін простяг з висоти Свою Руку, і мене звільнив\nВід усіх небезпек, від усіх ворогів.\n\nКуплет 2\nГосподь - Моя Скеля, Твердиня Моя,\nІ Він є Мій Спаситель.\nВін Світло Моє, Справедливий Господь,\nМогутній Вседержитель.\n\nКуплет  Пред Приспів\nЯ кличу: Преславний Господь!\nІ Він визволить від ворогів.\nВ тісноті я покличу Його,\nЩоб з Небес Він мені відповів.\n\nКуплет Приспів\nВін почує мій голос із Храму Свого,\nБо підношу молитви мої до Лиця Його.\nВін простяг з висоти Свою Руку, і мене звільнив\nВід усіх небезпек, від усіх ворогів.', '', '', '', '', 'ua', 1, NULL);